func write_health_snapshot(reason: String = "manual") -> bool:
    var encoded := JSON.stringify(build_health_snapshot(reason), "  ")
    var encoded_bytes := encoded.to_utf8_buffer().size()
    if encoded_bytes > MAX_HEALTH_FILE_BYTES:
        last_error = "health_snapshot_too_large"
        return false

    var temp := FileAccess.open(HEALTH_TEMP_PATH, FileAccess.WRITE)
    if temp == null:
        last_error = "health_temp_open_failed"
        return false
    if not temp.store_string(encoded):
        last_error = "health_temp_write_failed"
        return false
    temp.flush()
    if temp.get_error() != OK:
        last_error = "health_temp_flush_failed"
        return false
    temp = null

    var health_global := ProjectSettings.globalize_path(HEALTH_PATH)
    var temp_global := ProjectSettings.globalize_path(HEALTH_TEMP_PATH)
    var backup_global := ProjectSettings.globalize_path(HEALTH_BACKUP_PATH)
    if FileAccess.file_exists(HEALTH_PATH):
        DirAccess.remove_absolute(backup_global)
        var backup_error := DirAccess.copy_absolute(health_global, backup_global)
        if backup_error != OK:
            DirAccess.remove_absolute(temp_global)
            last_error = "health_backup_failed"
            return false

    var promote_error := DirAccess.rename_absolute(temp_global, health_global)
    if promote_error != OK:
        DirAccess.remove_absolute(temp_global)
        if not FileAccess.file_exists(HEALTH_PATH) and FileAccess.file_exists(HEALTH_BACKUP_PATH):
            DirAccess.copy_absolute(backup_global, health_global)
        last_error = "health_promote_failed"
        return false
    return true

func _rotate_event_log_if_needed(incoming_bytes: int) -> void:
    if incoming_bytes > MAX_EVENT_FILE_BYTES:
        last_error = "event_record_exceeds_log_capacity"
        return
    if not FileAccess.file_exists(EVENT_PATH):
        return
    var file := FileAccess.open(EVENT_PATH, FileAccess.READ)
    if file == null:
        last_error = "event_log_size_check_failed"
        return
    if file.get_length() + incoming_bytes <= MAX_EVENT_FILE_BYTES:
        return
    file = null
    var event_global := ProjectSettings.globalize_path(EVENT_PATH)
    var global_path := ProjectSettings.globalize_path(EVENT_BACKUP_PATH)
    DirAccess.remove_absolute(global_path)
    var backup_global := global_path
    var rotate_error := DirAccess.rename_absolute(event_global, backup_global)
    if rotate_error != OK:
        last_error = "event_log_rotate_failed"

func _notification(what: int) -> void:
    if what == NOTIFICATION_APPLICATION_PAUSED:
        record_event("application_paused")
        write_health_snapshot("application_paused")
    elif what == NOTIFICATION_APPLICATION_RESUMED:
        record_event("application_resumed")
        write_health_snapshot("application_resumed")
    elif what == NOTIFICATION_WM_CLOSE_REQUEST:
        record_event("close_requested")
        write_health_snapshot("close_requested")

