const SAVE_PATH := "user://hayat_tounes_save.json"
const TEMP_PATH := "user://hayat_tounes_save.tmp"
const BACKUP_PATH := "user://hayat_tounes_save.backup.json"
const MAX_SAVE_BYTES := 4 * 1024 * 1024

