func save_game(extra := {}) -> bool:
    last_error = ""
    last_migration_source = "none"
    var payload := _build_payload(extra)
    var payload_json := JSON.stringify(payload)
    var envelope := {
        "schema_version": SAVE_SCHEMA_VERSION,
        "build_version": _current_build_version(),
        "saved_at_utc": Time.get_datetime_string_from_system(true),
        "payload_sha256": _payload_hash(payload),
        "payload": payload
    }
    var encoded := JSON.stringify(envelope)
    if encoded.to_utf8_buffer().size() > MAX_SAVE_BYTES:
        last_error = "save_too_large"
        return false

    if not _write_text(TEMP_PATH, encoded):
        last_error = "temp_write_failed"
        return false

    var temp_global := ProjectSettings.globalize_path(TEMP_PATH)
    var save_global := ProjectSettings.globalize_path(SAVE_PATH)
    var backup_global := ProjectSettings.globalize_path(BACKUP_PATH)

    if FileAccess.file_exists(SAVE_PATH):
        if FileAccess.file_exists(BACKUP_PATH):
            DirAccess.remove_absolute(backup_global)
        var backup_result := DirAccess.copy_absolute(save_global, backup_global)
        if backup_result != OK:
            DirAccess.remove_absolute(temp_global)
            last_error = "backup_failed:%s" % backup_result
            return false

    if FileAccess.file_exists(SAVE_PATH):
        var remove_result := DirAccess.remove_absolute(save_global)
        if remove_result != OK:
            DirAccess.remove_absolute(temp_global)
            last_error = "replace_remove_failed:%s" % remove_result
            return false

    var rename_result := DirAccess.rename_absolute(temp_global, save_global)
    if rename_result != OK:
        last_error = "replace_rename_failed:%s" % rename_result
        if FileAccess.file_exists(BACKUP_PATH) and not FileAccess.file_exists(SAVE_PATH):
            DirAccess.copy_absolute(backup_global, save_global)
        return false

    return true

func load_game() -> Dictionary:
    last_error = ""
    last_load_source = "none"
    last_migration_source = "none"

    var primary := _read_and_validate(SAVE_PATH)
    if primary.get("valid", false):
        last_load_source = "primary"
        return _apply_payload(_migrate_payload(primary))

    var backup := _read_and_validate(BACKUP_PATH)
    if backup.get("valid", false):
        last_load_source = "backup"
        last_error = "primary_invalid_recovered_from_backup"
        return _apply_payload(_migrate_payload(backup))

    if FileAccess.file_exists(SAVE_PATH) or FileAccess.file_exists(BACKUP_PATH):
        last_error = "no_valid_save"
    return {}

