func _ready() -> void:
    process_mode = Node.PROCESS_MODE_ALWAYS
    started_unix = int(Time.get_unix_time_from_system())
    session_id = "%s-%s" % [started_unix, randi()]

    var previous := _read_previous_guard()
    var evaluation := evaluate_previous_marker(previous, started_unix)
    previous_session_unclean = bool(evaluation.get("previous_session_unclean", false))
    crash_count = int(evaluation.get("crash_count", 0))
    safe_mode = bool(evaluation.get("safe_mode", false))
    recovery_reason = str(evaluation.get("reason", "none"))

    if marker_source == "backup":
        recovery_reason = "guard_backup_recovered:%s" % recovery_reason

    # If neither primary nor backup can be trusted, fail closed for this session
    # without overwriting the user's persisted quality preference.
    if not last_error.is_empty():
        previous_session_unclean = true
        safe_mode = true
        recovery_reason = "guard_primary_and_backup_unreadable"

    if safe_mode:
        SettingsService.set_quality_mode("LOW", false)

    _write_marker("running")
    RuntimeDiagnostics.note_session_guard(
        previous_session_unclean,
        crash_count,
        safe_mode,
        recovery_reason,
        marker_source
    )

func evaluate_previous_marker(marker: Dictionary, now_unix: int) -> Dictionary:
    if marker.is_empty():
        return {
            "previous_session_unclean": false,
            "crash_count": 0,
            "safe_mode": false,
            "reason": "none"
        }

    var status := str(marker.get("status", "unknown"))
    if status != "running":
        return {
            "previous_session_unclean": false,
            "crash_count": 0,
            "safe_mode": false,
            "reason": "previous_%s" % status
        }

    var updated_unix := int(marker.get("updated_unix", 0))
    var previous_crash_count := maxi(0, int(marker.get("crash_count", 0)))
    var age := now_unix - updated_unix
    var within_window := updated_unix > 0 and age >= 0 and age <= CRASH_WINDOW_SECONDS
    var next_crash_count := previous_crash_count + 1 if within_window else 1
    var should_safe_mode := next_crash_count >= CRASH_LOOP_THRESHOLD
    return {
        "previous_session_unclean": true,
        "crash_count": next_crash_count,
        "safe_mode": should_safe_mode,
        "reason": "crash_loop" if should_safe_mode else "unclean_previous_session"
    }

